Section Canon.
Context {fx : FPState}.
Variable SEGS : list Segment.

(* [comment removed for export] *)
Definition canon_cfg (R : bvmap 5 word) (p : Z) (M : word -> option byte) (model : Model) : config :=
  mkCfg (mkst (canon_regs R) (Z_to_bv 64 p) M (seg_rom SEGS)) model.

